styleText:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family:'Inter',sans-serif; background:var(--bg); color:var(--text); line-height:1.6; overflow-x:hidden; -webkit-font-smoothing:antialiased; }
    a { text-decoration:none; color:inherit; }

    @keyframes fadeInUp { from{opacity:0;transform:translateY(24px);}to{opacity:1;transform:translateY(0);} }
    @keyframes float { 0%,100%{transform:translateY(0);}50%{transform:translateY(-8px);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);}50%{opacity:.5;transform:scale(.85);} }
    @keyframes marquee { 0%{transform:translateX(0);}100%{transform:translateX(-50%);} }
    @keyframes progress { from{width:0;}to{width:var(--w);} }

    .fade-in-up{animation:fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both;}
    .d1{animation-delay:.1s;}.d2{animation-delay:.2s;}.d3{animation-delay:.3s;}.d4{animation-delay:.4s;}

    .container{width:100%;max-width:1200px;margin:0 auto;padding:0 32px;}
    .section{padding:100px 0;}
    .eyebrow{display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:18px;}
    .eyebrow-dot{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite;}
    .section-headline{font-size:clamp(30px,4vw,46px);font-weight:800;line-height:1.1;letter-spacing:-.025em;margin-bottom:14px;}
    .section-sub{font-size:16px;color:var(--muted);max-width:520px;line-height:1.7;}

    /* Buttons */
    .btn{display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;outline:none;}
    .btn-primary{background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15);}
    .btn-primary:hover{background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2);}
    .btn-accent{background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3);}
    .btn-accent:hover{background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4);}
    .btn-outline{background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2);}
    .btn-outline:hover{background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm);}

    /* ── NAVBAR ── */
    .navbar{position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 40px;height:64px;display:flex;align-items:center;justify-content:space-between;background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border);}
    .nav-logo{display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em;}
    .nav-logo-icon{width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center;}
    .nav-logo-icon svg{width:16px;height:16px;}
    .nav-links{display:flex;align-items:center;gap:2px;list-style:none;}
    .nav-links a{font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px;}
    .nav-links a:hover{color:var(--text);background:rgba(0,0,0,.04);}
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-chevron{font-size:9px;opacity:.45;}
    .nav-actions{display:flex;align-items:center;gap:10px;}
    .nav-item{position:relative;list-style:none;}
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron{transform:rotate(180deg);opacity:.7;}
    .mega-panel{position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-6px);background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);padding:24px;opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;z-index:999;}
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel{opacity:1;pointer-events:auto;transform:translateX(-50%) translateY(0);}
    .mega-panel::before{content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6;}
    .mega-panel::after{content:'';position:absolute;top:-18px;left:0;right:0;height:18px;}
    .mega-products{width:1040px;}
    .mega-cols{display:flex;align-items:flex-start;gap:0;}
    .mega-col{flex:1;padding:0 28px;border-right:1px solid var(--border-2);min-width:0;}
    .mega-col:first-child{padding-left:0;}
    .mega-col:last-child{border-right:none;}
    .mega-col-label{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid var(--border-2);}
    .mega-col-link{display:block;font-size:14px;color:var(--text);text-decoration:none;padding:7px 0;font-weight:500;transition:color .15s;}
    .mega-col-link:hover{color:var(--accent);}
    .mega-col-badge{font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--accent);background:rgba(205,177,139,.15);border-radius:3px;padding:2px 5px;margin-left:6px;vertical-align:middle;}
    .mega-col-featured{flex:0 0 200px !important;padding:0 0 0 28px !important;border-right:none !important;}
    .mega-featured-img{width:100%;height:110px;border-radius:var(--radius-sm);overflow:hidden;margin-bottom:12px;}
    .mega-featured-img img{width:100%;height:100%;object-fit:cover;}
    .mega-featured-desc{font-size:12.5px;color:var(--muted);line-height:1.65;margin-bottom:12px;}
    .mega-featured-link{font-size:12.5px;font-weight:600;color:var(--text);text-decoration:none;display:flex;align-items:center;gap:4px;}
    .mega-featured-link:hover{color:var(--accent);}

    /* ── HERO ── */
    .hero{min-height:100vh;display:flex;align-items:flex-start;position:relative;overflow:hidden;padding-top:64px;}
    .hero-bg-img{position:absolute;inset:0;z-index:0;}
    .hero-bg-img img{width:100%;height:100%;object-fit:cover;object-position:center top;}
    .hero-overlay{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(247,247,244,0) 0%,rgba(247,247,244,.15) 55%,rgba(247,247,244,.9) 90%);}
    .hero-overlay-top{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(10,12,18,.2) 0%,rgba(10,12,18,.05) 50%,transparent 70%);}
    .hero-inner{position:relative;z-index:1;width:100%;max-width:1000px;margin:0 auto;padding:0 32px;display:flex;flex-direction:column;align-items:center;gap:48px;padding-top:60px;padding-bottom:80px;}
    .hero-content{max-width:720px;text-align:center;display:flex;flex-direction:column;align-items:center;}
    .hero-badge{display:inline-flex;align-items:center;gap:8px;background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-full);padding:5px 14px 5px 6px;font-size:12px;font-weight:500;color:var(--muted);margin-bottom:28px;box-shadow:var(--shadow-xs);}
    .hero-badge-pill{background:var(--accent);color:var(--dark);border-radius:var(--radius-full);padding:3px 10px;font-size:11px;font-weight:700;letter-spacing:.04em;}
    .hero-headline{font-size:clamp(28px,3.8vw,46px);font-weight:900;line-height:1.06;letter-spacing:-.035em;margin-bottom:22px;color:var(--text);}
    .hero-headline em{font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;} h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .hero-sub { font-size:17px; color:var(--text); line-height:1.7; max-width:600px; margin-bottom:36px; }
    .hero-ctas{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:40px;justify-content:center;}
    .hero-proof{display:flex;align-items:center;gap:14px;}
    .avatar-stack{display:flex;align-items:center;}
    .avatar{width:30px;height:30px;border-radius:50%;border:2.5px solid var(--bg);margin-left:-8px;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;}
    .avatar:first-child{margin-left:0;}
    .av1{background:#6366F1;}.av2{background:#F59E0B;}.av3{background:#10B981;}.av4{background:#EF4444;}
    .proof-text{font-size:13px;color:var(--muted);font-weight:500;}
    .proof-text strong{color:var(--text);}
    .stars{color:#F59E0B;font-size:12px;}

    /* Hero UI Card — QuikTrack style */
    .hero-visual{flex-shrink:0;width:460px;animation:float 6s ease-in-out infinite;}
    .track-card{background:var(--white);border-radius:var(--radius-xl);box-shadow:var(--shadow-xl);border:1px solid var(--border);overflow:hidden;}
    .track-header{padding:14px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;}
    .track-title{font-size:13px;font-weight:700;color:var(--text);}
    .track-badge{font-size:10px;font-weight:700;background:rgba(99,102,241,.1);color:#4F46E5;padding:3px 10px;border-radius:var(--radius-full);}
    .track-tabs{display:flex;gap:0;border-bottom:1px solid var(--border);}
    .track-tab{flex:1;padding:9px 0;text-align:center;font-size:11px;font-weight:600;color:var(--muted);border-right:1px solid var(--border);cursor:pointer;}
    .track-tab:last-child{border-right:none;}
    .track-tab.active{color:var(--text);background:rgba(0,0,0,.02);}
    .task-list{padding:12px 16px;display:flex;flex-direction:column;gap:6px;}
    .task-row{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:var(--radius-sm);background:var(--bg);border:1px solid var(--border);}
    .task-check{width:16px;height:16px;border-radius:4px;border:1.5px solid var(--border-2);flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:10px;}
    .task-check.done{background:var(--accent);border-color:var(--accent);color:var(--dark);}
    .task-info{flex:1;min-width:0;}
    .task-name{font-size:12px;font-weight:700;color:var(--text);}
    .task-name.done-text{text-decoration:line-through;color:var(--muted);}
    .task-meta{font-size:10px;color:var(--muted);margin-top:1px;}
    .task-time{font-size:11px;font-weight:700;}
    .task-time.over{color:#EF4444;}
    .task-time.ok{color:#16A34A;}
    .task-prog{width:100%;margin-top:4px;}
    .prog-bar{height:3px;border-radius:2px;background:var(--border-2);overflow:hidden;}
    .prog-fill{height:100%;border-radius:2px;background:var(--accent);}
    .ai-bar{padding:10px 16px;background:rgba(205,177,139,.08);border-top:1px solid var(--border);display:flex;align-items:center;gap:8px;}
    .ai-bar-icon{width:22px;height:22px;border-radius:6px;background:var(--accent);display:flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;}
    .ai-bar-text{font-size:11px;color:var(--text);font-weight:500;flex:1;}
    .ai-bar-text span{color:var(--accent);font-weight:700;}

    /* ── PROBLEM ── */
    .problem-section{background:var(--white);}
    .problem-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;}
    .problem-visual{position:relative;border:3px solid #E6E6E3;border-radius:var(--radius-xl);overflow:hidden;}
    .chaos-card{background:var(--bg);border:1px solid var(--border-2);border-radius:var(--radius-lg);padding:24px;margin-bottom:16px;position:relative;}
    .chaos-card::before{content:attr(data-label);position:absolute;top:-10px;left:16px;font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;background:var(--bg);padding:0 6px;color:var(--muted-2);}
    .chaos-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
    .chaos-row:last-child{margin-bottom:0;}
    .chaos-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;}
    .chaos-line{height:8px;border-radius:4px;background:var(--border-2);flex:1;}
    .chaos-x{font-size:16px;color:#EF4444;font-weight:900;flex-shrink:0;}
    .chaos-warning{display:flex;align-items:center;gap:8px;padding:10px 14px;background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.15);border-radius:var(--radius-sm);font-size:12px;font-weight:600;color:#DC2626;margin-top:12px;}
    .problem-points{display:flex;flex-direction:column;gap:20px;margin-top:32px;}
    .problem-point{display:flex;align-items:flex-start;gap:14px;}
    .problem-icon{width:36px;height:36px;border-radius:10px;background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.15);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0;}
    .problem-point-title{font-size:14px;font-weight:700;margin-bottom:4px;}
    .problem-point-desc{font-size:13px;color:var(--muted);line-height:1.6;}

    /* ── SOLUTION / LOOP ── */
    .solution-section{background:var(--bg);}
    .solution-grid { display:grid; grid-template-columns:1fr 1fr; gap:80px; align-items:center; }
    .solution-points { display:flex; flex-direction:column; gap:24px; margin-top:32px; }
    .solution-point { display:flex; align-items:flex-start; gap:14px; }
    .solution-check { width:22px; height:22px; border-radius:6px; background:rgba(22,163,74,.12); border:1px solid rgba(22,163,74,.2); display:flex; align-items:center; justify-content:center; font-size:12px; flex-shrink:0; margin-top:2px; }
    .solution-point-title { font-size:14px; font-weight:700; margin-bottom:4px; }
    .solution-point-desc { font-size:13px; color:var(--muted); line-height:1.6; }
    .pipeline-visual { background:transparent; border-radius:var(--radius-xl); box-shadow:none; border:3px solid #E6E6E3; overflow:hidden; aspect-ratio:auto; }
    .loop-steps{display:flex;align-items:center;justify-content:center;gap:0;margin:48px 0;position:relative;}
    .loop-step{display:flex;flex-direction:column;align-items:center;text-align:center;position:relative;z-index:1;}
    .loop-circle{width:60px;height:60px;border-radius:50%;background:var(--white);border:2px solid var(--border-2);display:flex;align-items:center;justify-content:center;font-size:22px;box-shadow:var(--shadow-sm);margin-bottom:12px;transition:all .2s;}
    .loop-circle.active{border-color:var(--accent);background:rgba(205,177,139,.08);box-shadow:0 0 0 6px rgba(205,177,139,.12);}
    .loop-arrow{font-size:18px;color:var(--accent);margin:0 16px;margin-bottom:36px;font-weight:900;}
    .loop-label{font-size:13px;font-weight:700;color:var(--text);}
    .loop-sub{font-size:11px;color:var(--muted);margin-top:3px;max-width:80px;}
    .value-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:16px;}
    .value-card{background:var(--white);border:1px solid var(--border);border-radius:var(--radius-lg);padding:24px;transition:box-shadow .2s,transform .2s;}
    .value-card:hover{box-shadow:var(--shadow-md);transform:translateY(-3px);}
    .value-num{font-size:32px;margin-bottom:12px;}
    .value-title{font-size:15px;font-weight:800;margin-bottom:6px;letter-spacing:-.02em;}
    .value-desc{font-size:13px;color:var(--muted);line-height:1.6;}

    /* ── FEATURES ── */
    .features-section{background:var(--white);}
    .features-header{text-align:center;margin-bottom:64px;}
    .features-header .section-sub{margin:0 auto;text-align:center;}
    .features-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;}
    .feature-card{background:var(--bg);border:1px solid var(--border);border-radius:var(--radius-lg);padding:32px 28px;transition:box-shadow .2s,transform .2s;}
    .feature-card:hover{box-shadow:var(--shadow-md);transform:translateY(-3px);border-color:var(--border-2);}
    .feature-icon{width:44px;height:44px;border-radius:12px;background:var(--white);border:1px solid var(--border-2);display:flex;align-items:center;justify-content:center;font-size:20px;margin-bottom:18px;box-shadow:var(--shadow-xs);}
    .feature-title{font-size:17px;font-weight:800;margin-bottom:10px;}
    .feature-desc{font-size:13px;color:var(--muted);line-height:1.7;margin-bottom:18px;}
    .feature-list{list-style:none;display:flex;flex-direction:column;gap:8px;}
    .feature-list li{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted);}
    .feature-list li::before{content:'✓';color:var(--accent);font-weight:900;font-size:12px;flex-shrink:0;}
    .feature-card.featured{background:var(--dark);border-color:var(--dark);color:#fff;}
    .feature-card.featured .feature-icon{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.12);}
    .feature-card.featured .feature-title{color:#fff;}
    .feature-card.featured .feature-desc{color:rgba(255,255,255,.55);}
    .feature-card.featured .feature-list li{color:rgba(255,255,255,.6);}
    .feature-card.featured .feature-list li::before{color:var(--accent);}

    /* ── WORKFLOW ── */
    .workflow-section{background:var(--bg);}
    .workflow-header{text-align:center;margin-bottom:64px;}
    .workflow-header .section-sub{margin:0 auto;}
    .workflow-steps{display:grid;grid-template-columns:repeat(5,1fr);gap:0;align-items:center;margin-bottom:60px;}
    .workflow-step{text-align:center;position:relative;}
    .workflow-connector{height:2px;background:linear-gradient(to right,var(--accent),rgba(205,177,139,.3));margin-top:-24px;position:relative;}
    .workflow-connector::after{content:'→';position:absolute;right:-8px;top:-10px;color:var(--accent);font-size:14px;font-weight:900;}
    .step-circle{width:48px;height:48px;border-radius:50%;background:var(--white);border:2px solid var(--border-2);display:flex;align-items:center;justify-content:center;font-size:20px;margin:0 auto 12px;position:relative;z-index:1;box-shadow:var(--shadow-sm);}
    .step-circle.active{border-color:var(--accent);background:rgba(205,177,139,.08);box-shadow:0 0 0 4px rgba(205,177,139,.15);}
    .step-num{position:absolute;top:-6px;right:-6px;width:18px;height:18px;background:var(--dark);color:#fff;border-radius:50%;font-size:9px;font-weight:900;display:flex;align-items:center;justify-content:center;}
    .step-label{font-size:13px;font-weight:700;color:var(--text);margin-bottom:4px;}
    .step-sub{font-size:11px;color:var(--muted);line-height:1.4;max-width:90px;margin:0 auto;}
    .workflow-ai-bar{background:var(--dark);border-radius:var(--radius-lg);padding:24px 32px;display:flex;align-items:center;gap:24px;}
    .wf-ai-icon{font-size:28px;flex-shrink:0;}
    .wf-ai-label{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.4);margin-bottom:4px;}
    .wf-ai-text{font-size:15px;font-weight:600;color:#fff;}
    .wf-ai-pills{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto;}
    .wf-pill{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);border-radius:var(--radius-full);padding:5px 14px;font-size:11px;font-weight:600;color:rgba(255,255,255,.6);}
    .wf-pill.active{background:rgba(205,177,139,.15);border-color:rgba(205,177,139,.3);color:var(--accent);}

    /* ── METRICS ── */
    .metrics-section{background:var(--white);}
    .metrics-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--border-2);border-radius:var(--radius-lg);overflow:hidden;border:1px solid var(--border-2);}
    .metric-cell{background:var(--white);padding:40px 32px;}
    .metric-num{font-size:clamp(36px,4vw,52px);font-weight:900;letter-spacing:-.04em;color:var(--text);line-height:1;margin-bottom:8px;}
    .metric-num span{color:var(--accent);}
    .metric-label{font-size:14px;color:var(--muted);line-height:1.5;}

    /* ── INTEGRATIONS ── */
    .integrations-section{background:var(--bg);overflow:hidden;}
    .integrations-header{text-align:center;margin-bottom:48px;}
    .integrations-header .section-sub{margin:0 auto;}
