(function() {
  var steps = document.querySelector('.workflow-steps');
  if (!steps || window.innerWidth > 768) return;
  function isInView() {
    var r = steps.getBoundingClientRect();
    return r.top <= window.innerHeight * 0.6 && r.bottom >= window.innerHeight * 0.2;
  }
  function atEnd() { return steps.scrollLeft + steps.clientWidth >= steps.scrollWidth - 10; }
  function atStart() { return steps.scrollLeft <= 5; }
  window.addEventListener('wheel', function(e) {
    if (!isInView()) return;
    if (atEnd() && e.deltaY > 0) return;
    if (atStart() && e.deltaY < 0) return;
    e.preventDefault();
    steps.scrollBy({ left: e.deltaY * 1.5, behavior: "smooth" });
  }, { passive: false });
  var tStartX = 0, tStartY = 0, tScrollLeft = 0;
  document.addEventListener('touchstart', function(e) {
    tStartX = e.touches[0].clientX;
    tStartY = e.touches[0].clientY;
    tScrollLeft = steps.scrollLeft;
  }, { passive: true });
  document.addEventListener('touchmove', function(e) {
    if (!isInView()) return;
    var dx = tStartX - e.touches[0].clientX;
    var dy = tStartY - e.touches[0].clientY;
    if (Math.abs(dx) >= Math.abs(dy)) return;
    if (atEnd() && dy > 0) return;
    if (atStart() && dy < 0) return;
    e.preventDefault();
    steps.scrollLeft = tScrollLeft + dy * 1.2;
  }, { passive: false });
})()

(function() {
    document.querySelectorAll('.nav-item.has-mega').forEach(function(item) {
      var panel = item.querySelector('.mega-panel');
      var timer;
      function openMenu()  { clearTimeout(timer); item.classList.add('mega-open'); }
      function closeMenu() { timer = setTimeout(function() { item.classList.remove('mega-open'); }, 120); }
      item.addEventListener('mouseenter', openMenu);
      item.addEventListener('mouseleave', closeMenu);
      if (panel) {
        panel.addEventListener('mouseenter', openMenu);
        panel.addEventListener('mouseleave', closeMenu);
      }
    });
  })();

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) { item.classList.add('open'); icon.textContent = '−'; }
  }

(function(){
  var overlay=document.getElementById('wc-overlay'),canvas=document.getElementById('wc-canvas'),turb=document.getElementById('wc-turb');
  if(turb)turb.setAttribute('seed',Math.floor(Math.random()*120)+1);
  var ctx=canvas.getContext('2d'),W,H;
  function resize(){W=canvas.width=window.innerWidth;H=canvas.height=window.innerHeight;}
  resize();window.addEventListener('resize',resize);
  function easeOut(t){return 1-Math.pow(1-t,1.8);}
  function maxCornerDist(ox,oy){return Math.max(Math.hypot(ox,oy),Math.hypot(W-ox,oy),Math.hypot(ox,H-oy),Math.hypot(W-ox,H-oy));}
  var drops=[{fx:0.22,fy:0.20,reach:1.35,lag:0.00},{fx:0.78,fy:0.32,reach:1.30,lag:0.06},{fx:0.48,fy:0.78,reach:1.25,lag:0.10}];
  var DURATION=3400,startTime=null;
  function frame(ts){
    if(!startTime)startTime=ts;
    var progress=Math.min((ts-startTime)/DURATION,1);
    ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.fillStyle='#F7F7F4';ctx.fillRect(0,0,W,H);
    ctx.globalCompositeOperation='destination-out';
    drops.forEach(function(d){
      var t=Math.max(0,Math.min((progress-d.lag)/(1-d.lag),1)),e=easeOut(t),ox=d.fx*W,oy=d.fy*H,r=e*maxCornerDist(ox,oy)*d.reach;
      if(r<1)return;
      var g=ctx.createRadialGradient(ox,oy,r*0.30,ox,oy,r);
      g.addColorStop(0.00,'rgba(0,0,0,1)');g.addColorStop(0.50,'rgba(0,0,0,0.98)');g.addColorStop(0.70,'rgba(0,0,0,0.85)');
      g.addColorStop(0.82,'rgba(0,0,0,0.55)');g.addColorStop(0.92,'rgba(0,0,0,0.20)');g.addColorStop(1.00,'rgba(0,0,0,0)');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(ox,oy,r,0,Math.PI*2);ctx.fill();
    });
    ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
    if(progress<1){requestAnimationFrame(frame);}
    else{overlay.style.transition='opacity 0.45s ease';overlay.style.opacity='0';setTimeout(function(){overlay.remove();},550);}
  }
  requestAnimationFrame(frame);
})();
